from taf.sw.dcap.rd.interfaces.dcap_base import DCAP
from taf.sw.dcap.rd.schemas.cm.start_trace_v1 import StartTraceV1
from taf.sw.dcap.rd.services.cm.cm_v1 import CMv1
from taf.sw.dcap.rd.auth.authorization import TokenProvider
from taf.internal.sw.dcap.rd.client.dcap_lite.v3.configuration import Configuration


class DCAPv1(DCAP):
    cm = None

    def __init__(self, con_details, token=None):
        super(DCAPv1, self).__init__()
        self.token = token
        if token:
            self.cm = CMv1(con_details=con_details)
            self.token_subscribers = [self.cm]
        else:
            conf = Configuration()
            conf.client_side_validation = True
            conf.verify_ssl = False
            conf.host = con_details.make_configuration_host(original_endpoint=conf.host)
            self.cm = CMv1(con_details=con_details)

    @TokenProvider.provide_access_token
    def start_trace(self, bts, tag='start_trace', duration=-1, force=True, gnb_trace_profile=None,
                    enb_trace_profile=None, bts_trace_profile=None, vcu_trace_profile=None, vdu_trace_profile=None,
                    custom_filter_file=None, gnb_custom_profile=None,
                    enb_custom_profile=None, resource_group=None,
                    allow_start_failures=None, control_plane_interface=None, wait_for_activation=False, timeout=400):
        start_trace_body = self.cm.start_trace(bts=bts, tag=tag, duration=duration, force=force,
                                               gnb_trace_profile=gnb_trace_profile,
                                               enb_trace_profile=enb_trace_profile,
                                               custom_filter_file=custom_filter_file,
                                               gnb_custom_profile=gnb_custom_profile,
                                               enb_custom_profile=enb_custom_profile,
                                               wait_for_activation=wait_for_activation,
                                               control_plane_interface=control_plane_interface,
                                               timeout=timeout)
        return StartTraceV1.from_object_dict(data=start_trace_body)
